@app.post("/api/content/upload")
async def upload_content(
    request: Request,
    current_user: Dict[str, Any] = Depends(get_current_user)
):
    """
    Upload educational content.
    Rate limited per user.
    """
    # Check rate limits
    await check_user_rate_limit(
        current_user['user_id'],
        settings.rate_limit_per_user,
        settings.rate_limit_window_hours
    )
    await check_global_rate_limit(
        settings.rate_limit_global,
        settings.rate_limit_window_hours
    )

    # Get form data
    form = await request.form()

    # Forward to document processor
    async with httpx.AsyncClient(timeout=300.0) as client:
        files = {}
        data = {"user_id": current_user['user_id']}

        for key, value in form.items():
            if hasattr(value, 'file'):
                # It's a file
                files[key] = (value.filename, value.file, value.content_type)
            else:
                # It's form data
                data[key] = value

        response = await make_service_request(
            client, "POST", f"{settings.document_processor_url}/api/content/upload",
            request, files=files, data=data
        )

        if response.status_code != 200:
            raise HTTPException(status_code=response.status_code, detail=response.text)

        return response.json()


@app.post("/api/documents/bulk-upload")
async def bulk_upload_documents(
    request: Request,
    current_user: Dict[str, Any] = Depends(get_current_user)
):
    """
    Bulk upload multiple documents.
    Rate limited per user with higher limits for batch uploads.
    """
    # Check rate limits (more lenient for batch uploads)
    await check_user_rate_limit(
        current_user['user_id'],
        settings.rate_limit_per_user * 10,  # Allow 10x normal rate for batches
        settings.rate_limit_window_hours
    )
    await check_global_rate_limit(
        settings.rate_limit_global * 5,  # Allow 5x normal rate globally
        settings.rate_limit_window_hours
    )

    # Get form data
    form = await request.form()

    # Forward to document processor with extended timeout
    async with httpx.AsyncClient(timeout=600.0) as client:
        files = []
        data = {"user_id": current_user['user_id']}

        for key, value in form.items():
            if hasattr(value, 'file'):
                # Collect all files (multiple files with same key name)
                files.append(('files', (value.filename, value.file, value.content_type)))
            else:
                # It's form data
                data[key] = value

        response = await make_service_request(
            client, "POST", f"{settings.document_processor_url}/api/documents/bulk-upload",
            request, files=files, data=data
        )

        if response.status_code != 200:
            raise HTTPException(status_code=response.status_code, detail=response.text)

        return response.json()


@app.get("/api/documents/batch/{batch_id}")
async def get_batch_status(
    batch_id: str,
    current_user: Dict[str, Any] = Depends(get_current_user)
):
    """
    Get status of a batch upload.
    """
    async with httpx.AsyncClient(timeout=10.0) as client:
        response = await client.get(
            f"{settings.document_processor_url}/api/documents/batch/{batch_id}"
        )

        if response.status_code != 200:
            raise HTTPException(status_code=response.status_code, detail=response.text)

        return response.json()

