                {isBatchUpload
                  ? 'This subject will be applied to all uploaded documents'
                  : 'Enter the subject area for this document'}
              </p>
            </div>

            <div className="space-y-2">
              <Label htmlFor="tags">Tags (comma-separated) {isBatchUpload && '(applies to all files)'}</Label>
              <Input
                id="tags"
                placeholder="e.g., stoichiometry, moles, calculations"
                value={tags}
                onChange={(e) => setTags(e.target.value)}
                disabled={isUploading || uploadSuccess}
              />
              <p className="text-xs text-muted-foreground">
                {isBatchUpload
                  ? 'These tags will be applied to all uploaded documents'
                  : 'Add tags to help organize and find your documents'}
              </p>
            </div>
          </div>

          {/* Info message */}
          {!uploadSuccess && !isUploading && (
            <Alert>
              <Info className="h-4 w-4" />
              <AlertDescription>
                {isBatchUpload ? (
                  <>
