                    Your document will be processed automatically with real-time status updates.
                    You'll be able to chat with it once processing is complete (usually 1-2 minutes).
                  </>
                )}
              </AlertDescription>
            </Alert>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={handleClose} disabled={isUploading}>
            {uploadSuccess ? 'Close' : 'Cancel'}
          </Button>
          {!uploadSuccess && (
            <Button onClick={handleUpload} disabled={!isFormValid || isUploading}>
              {isUploading ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  {isBatchUpload ? 'Processing...' : 'Uploading...'}
                </>
              ) : (
                <>
                  <Upload className="mr-2 h-4 w-4" />
                  {isBatchUpload ? `Upload All (${files.length})` : 'Upload'}
                </>
              )}
            </Button>
          )}
        </DialogFooter>
      </DialogContent>

      {/* Batch Results Modal */}
      <BatchResultsModal
        open={showResultsModal}
        onOpenChange={handleResultsClose}
        totalFiles={totalBatchFiles + rejectedFiles.length}
        completedFiles={batchCompleted}
        failedFiles={batchFailed}
        rejectedFiles={rejectedFiles}
      />
    </Dialog>
  )
}

