/**
 * UploadDialog Component
 * Modal dialog for uploading new documents with metadata
 */

import { useState, useEffect } from 'react'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '../../../components/ui/dialog'
import { Button } from '../../../components/ui/Button'
import { Input } from '../../../components/ui/Input'
import { Label } from '../../../components/ui/label'
import { FileUploader } from '../../../components/ui/FileUploader'
import { Badge } from '../../../components/ui/Badge'
import { Alert, AlertDescription } from '../../../components/ui/alert'
import { Progress } from '../../../components/ui/progress'
import { Info, Upload, CheckCircle, Loader2 } from 'lucide-react'
import { Document } from '../../../api/types'
import { useAuth } from '../../auth/hooks/useAuth'
import { BatchUploadProgress } from './BatchUploadProgress'
import { BatchResultsModal } from './BatchResultsModal'
import { documentsService } from '../../../api/documents.service'

interface UploadDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  onUploadComplete?: (document: Document) => void
}

export function UploadDialog({ open, onOpenChange, onUploadComplete }: UploadDialogProps) {
  const { user } = useAuth()
  const [files, setFiles] = useState<File[]>([])
  const [title, setTitle] = useState('')
  const [subject, setSubject] = useState('')
  const [tags, setTags] = useState('')
  const [isUploading, setIsUploading] = useState(false)
  const [uploadSuccess, setUploadSuccess] = useState(false)
  const [uploadedDoc, setUploadedDoc] = useState<Document | null>(null)
  const [processingStatus, setProcessingStatus] = useState('')
  const [processingProgress, setProcessingProgress] = useState(0)

  // Batch upload states
  const [isBatchUpload, setIsBatchUpload] = useState(false)
  const [batchId, setBatchId] = useState<string | null>(() => {
    // Restore active batch from sessionStorage (tab-specific, not shared across tabs)
    const saved = sessionStorage.getItem('active_batch_id')
    return saved || null
  })
  const [totalBatchFiles, setTotalBatchFiles] = useState(() => {
    const saved = sessionStorage.getItem('active_batch_total_files')
    return saved ? parseInt(saved, 10) : 0
  })
  const [showResultsModal, setShowResultsModal] = useState(false)
  const [batchCompleted, setBatchCompleted] = useState(0)
  const [batchFailed, setBatchFailed] = useState(0)
  const [rejectedFiles, setRejectedFiles] = useState<Array<{ filename: string; reason: string }>>([])

  // Auto-recover from page refresh if batch is in progress
  useEffect(() => {
    if (batchId && totalBatchFiles > 0 && !open) {
      // We have an active batch but dialog is closed (likely from refresh)
      // Automatically re-open dialog to show progress
      onOpenChange(true)
      setIsBatchUpload(true)
      setIsUploading(true)
    }
  }, [batchId, totalBatchFiles, open, onOpenChange])

  const handleFilesChange = (newFiles: File[]) => {
    setFiles(newFiles)
    setIsBatchUpload(newFiles.length > 1)

    // Auto-fill title from filename if empty (for single file only)
    if (newFiles.length === 1 && !title) {
      const filename = newFiles[0].name.replace(/\.[^/.]+$/, '') // Remove extension
      setTitle(filename)
    }
  }

  const handleUpload = async () => {
    if (files.length === 0 || !user) return

    // Handle batch upload (multiple files)
    if (isBatchUpload) {
      await handleBatchUpload()
      return
    }

    // Handle single file upload
    setIsUploading(true)
    setUploadSuccess(false)
    setProcessingStatus('Uploading file...')
    setProcessingProgress(0)

    try {
      const file = files[0]

      // Upload document via real API
      const apiBaseUrl = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8000'

      if (!user) {
        throw new Error('User not authenticated')
      }

      const formData = new FormData()
      formData.append('file', file)
      formData.append('user_id', user.id)
      formData.append('title', title || file.name)
      if (subject) formData.append('subject', subject)
      if (tags) formData.append('tags', tags)

      const response = await fetch(`${apiBaseUrl}/api/content/upload`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${localStorage.getItem('access_token')}`,
        },
        body: formData,
      })

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}))
        throw new Error(errorData.detail || errorData.message || 'Upload failed')
      }

      const document = await response.json()
      setUploadedDoc(document)

      setProcessingStatus('Upload complete - processing document...')
      setProcessingProgress(10)

      // Connect to WebSocket for real-time status
      if (!document.is_duplicate) {
        connectWebSocket(document.content_id)
      } else {
        setUploadSuccess(true)
        setProcessingStatus('Duplicate detected - linked to your account')
        setProcessingProgress(100)

        if (onUploadComplete) {
          onUploadComplete(document)
        }

        // Reset form after status complete
        setTimeout(() => {
          handleClose()
        }, 2000)
      }
    } catch (error: any) {
      console.error('Upload error:', error)
      const errorMessage = error.message || 'Unknown error occurred'
      setProcessingStatus(`Upload failed: ${errorMessage}`)
      setUploadSuccess(false)
      setProcessingProgress(0)
    } finally {
      setIsUploading(false)
    }
  }

  const handleBatchUpload = async () => {
    if (!user) return

    setIsUploading(true)
    setUploadSuccess(false)
    setProcessingStatus('Starting batch upload...')

    try {
      const response = await documentsService.bulkUploadDocuments({
        files,
        user_id: user.id,
        subject: subject || undefined,
        tags: tags || undefined,
      })

      setBatchId(response.batch_id)
      setTotalBatchFiles(response.accepted_files)
      setRejectedFiles(response.rejected_files)

      // Persist to localStorage for recovery after refresh
      localStorage.setItem('active_batch_id', response.batch_id)
      localStorage.setItem('active_batch_total_files', response.accepted_files.toString())
      setProcessingStatus(`Processing ${response.accepted_files} files...`)

      // Don't setIsUploading(false) here - keep it until batch completes
    } catch (error: any) {
      console.error('Batch upload error:', error)
      const errorMessage = error.message || 'Batch upload failed'
      setProcessingStatus(`Upload failed: ${errorMessage}`)
      setUploadSuccess(false)
      setIsUploading(false)
    }
  }

  const handleBatchComplete = (completedCount: number, failedCount: number) => {
    setBatchCompleted(completedCount)
    setBatchFailed(failedCount)
    setUploadSuccess(true)
    setIsUploading(false)

    // Clear localStorage since batch is complete
    localStorage.removeItem('active_batch_id')
    localStorage.removeItem('active_batch_total_files')

    // Show results modal after a brief delay
    setTimeout(() => {
      setShowResultsModal(true)
    }, 500)
  }

  const handleRetry = () => {
    // Close results modal
    setShowResultsModal(false)

    // Reset batch state
    setBatchId(null)
    setBatchCompleted(0)
    setBatchFailed(0)

    // Keep files and rejected files for retry
    // User can remove successful files or adjust failed ones
    setUploadSuccess(false)

    // Note: Files are still in state, user can retry the same batch
  }

  const connectWebSocket = (contentId: string) => {
    const wsBaseUrl = import.meta.env.VITE_WS_BASE_URL || 'ws://localhost:8000'
    const ws = new WebSocket(`${wsBaseUrl}/ws/document/${contentId}/status`)
    let wsConnected = false
    let pollInterval: NodeJS.Timeout | null = null
    let heartbeatInterval: NodeJS.Timeout | null = null

    ws.onopen = () => {
      wsConnected = true
      heartbeatInterval = setInterval(() => {
        if (ws.readyState === WebSocket.OPEN) {
          ws.send(JSON.stringify({ type: 'ping' }))
        } else {
          if (heartbeatInterval) clearInterval(heartbeatInterval)
        }
      }, 25000)
    }

    ws.onmessage = (event) => {
      const data = JSON.parse(event.data)

      if (data.type === 'heartbeat' || data.type === 'pong') {
        return
      }

      setProcessingStatus(data.message || `Status: ${data.status}`)
      setProcessingProgress(data.progress || 0)

      if (data.status === 'completed') {
        setUploadSuccess(true)
        ws.close()
        if (heartbeatInterval) clearInterval(heartbeatInterval)
        if (pollInterval) clearInterval(pollInterval)

        // Notify parent with updated document
        if (uploadedDoc && onUploadComplete) {
          const completedDoc = { ...uploadedDoc, status: 'completed' as const }
          onUploadComplete(completedDoc)
        }

        // Close dialog after showing success
        setTimeout(() => {
          handleClose()
        }, 2000)
      } else if (data.status === 'failed') {
        setProcessingStatus('Processing failed')
        ws.close()
        if (heartbeatInterval) clearInterval(heartbeatInterval)
        if (pollInterval) clearInterval(pollInterval)
      }
    }

    ws.onerror = (error) => {
      console.error('WebSocket error:', error)
      setProcessingStatus('Connection issue - checking status...')

      // Fallback to polling after WebSocket error
      if (!pollInterval) {
        startPolling(contentId)
      }
    }

    ws.onclose = () => {
      if (heartbeatInterval) clearInterval(heartbeatInterval)

      // If closed unexpectedly and not yet completed, start polling
      if (wsConnected && !uploadSuccess) {
        console.log('WebSocket closed unexpectedly, starting polling')
        if (!pollInterval) {
          startPolling(contentId)
        }
      }
    }

    // Polling fallback function
    const startPolling = (contentId: string) => {
      let attempts = 0
      const maxAttempts = 150 // 5 minutes (150 * 2s)

      pollInterval = setInterval(async () => {
        attempts++

        if (attempts > maxAttempts) {
          if (pollInterval) clearInterval(pollInterval)
          setProcessingStatus('Processing timeout - please refresh')
          return
        }

        try {
          const doc = await documentsService.getDocument(contentId)

          if (doc.status === 'completed') {
            setUploadSuccess(true)
            setProcessingStatus('Document ready for chat!')
            setProcessingProgress(100)
            if (pollInterval) clearInterval(pollInterval)

            if (uploadedDoc && onUploadComplete) {
              const completedDoc = { ...uploadedDoc, status: 'completed' as const }
              onUploadComplete(completedDoc)
            }

            setTimeout(() => {
              handleClose()
            }, 2000)
          } else if (doc.status === 'failed') {
            setProcessingStatus('Processing failed')
            if (pollInterval) clearInterval(pollInterval)
          } else {
            // Calculate progress
            const progress = doc.total_chunks && doc.total_chunks > 0 
              ? Math.floor(((doc.processed_chunks || 0) / doc.total_chunks) * 100)
              : 0
            setProcessingProgress(progress)
            setProcessingStatus(`Processing... ${doc.processed_chunks || 0}/${doc.total_chunks || 0} chunks`)
          }
        } catch (error) {
          console.error('Failed to poll status:', error)
          // Continue polling despite errors
        }
      }, 2000) // Poll every 2 seconds
    }
  }

  const handleClose = () => {
    if (!isUploading) {
      setFiles([])
      setTitle('')
      setSubject('')
      setTags('')
      setUploadSuccess(false)
      setUploadedDoc(null)
      setProcessingStatus('')
      setProcessingProgress(0)
      setIsBatchUpload(false)
      setBatchId(null)
      setTotalBatchFiles(0)
      setBatchCompleted(0)
      setBatchFailed(0)
      setRejectedFiles([])
      onOpenChange(false)
    }
  }

  const handleResultsClose = () => {
    setShowResultsModal(false)
    handleClose()
    // Trigger a page refresh or callback if needed
    if (onUploadComplete && batchCompleted > 0) {
      // For batch uploads, we can't pass a single document
      // The parent should refresh the document list
      window.location.reload()
    }
  }

  const isFormValid = files.length > 0 && (isBatchUpload || title.trim() !== '')

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-[700px] max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Upload Document{isBatchUpload ? 's' : ''}</DialogTitle>
          <DialogDescription>
            {isBatchUpload
              ? `Upload up to 50 documents at once. Supported formats: PDF, TXT, MD, DOCX (Max 50MB per file, 500MB total)`
              : `Add a new document to your knowledge base. Supported formats: PDF, TXT, MD, DOCX`}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6 py-4">
          {/* File uploader */}
          <FileUploader
            onFilesChange={handleFilesChange}
            accept=".pdf,.txt,.md,.docx"
            maxSize={50 * 1024 * 1024}
            maxFiles={50}
            multiple={true}
            disabled={isUploading || uploadSuccess}
          />

          {/* Batch Upload Progress */}
          {isBatchUpload && batchId && isUploading && (
            <BatchUploadProgress
              batchId={batchId}
              totalFiles={totalBatchFiles}
              onComplete={handleBatchComplete}
            />
          )}

          {/* Processing status (for single file only) */}
          {!isBatchUpload && isUploading && processingStatus && (
            <Alert className="border-blue-200 bg-blue-50">
              <Loader2 className="h-4 w-4 text-blue-600 animate-spin" />
              <AlertDescription className="text-blue-800">
                <div className="space-y-2">
                  <div>{processingStatus}</div>
                  {processingProgress > 0 && (
                    <Progress value={processingProgress} className="h-2" />
                  )}
                </div>
              </AlertDescription>
            </Alert>
          )}

          {/* Success message */}
          {uploadSuccess && uploadedDoc && (
            <Alert className="border-green-200 bg-green-50">
              <CheckCircle className="h-4 w-4 text-green-600" />
              <AlertDescription className="text-green-800">
                {uploadedDoc.is_duplicate ? (
                  <>
                    Document already exists in knowledge base! Linked to your account.
                    <Badge variant="secondary" className="ml-2">
                      Duplicate Detected
                    </Badge>
                  </>
                ) : (
                  `Document processed successfully! ${processingProgress}% complete`
                )}
              </AlertDescription>
            </Alert>
