  // Auto-recover from page refresh if batch is in progress
  useEffect(() => {
    if (batchId && totalBatchFiles > 0 && !open) {
      // We have an active batch but dialog is closed (likely from refresh)
      // Automatically re-open dialog to show progress
      onOpenChange(true)
      setIsBatchUpload(true)
      setIsUploading(true)
    }
  }, [batchId, totalBatchFiles, open, onOpenChange])

  const handleFilesChange = (newFiles: File[]) => {
    setFiles(newFiles)
    setIsBatchUpload(newFiles.length > 1)

    // Auto-fill title from filename if empty (for single file only)
    if (newFiles.length === 1 && !title) {
      const filename = newFiles[0].name.replace(/\.[^/.]+$/, '') // Remove extension
      setTitle(filename)
    }
  }

  const handleUpload = async () => {
    if (files.length === 0 || !user) return

    // Handle batch upload (multiple files)
    if (isBatchUpload) {
      await handleBatchUpload()
      return
    }

    // Handle single file upload
    setIsUploading(true)
    setUploadSuccess(false)
    setProcessingStatus('Uploading file...')
    setProcessingProgress(0)

    try {
